static void dfs(int *c, int n, int target, int start, int *cur, int depth, int **res, int *size, int **cols) {
  if (target == 0) {
    res[*size] = (int *)malloc(sizeof(int) * depth);
    for (int i = 0; i < depth; i++) {
      res[*size][i] = cur[i];
    }
    (*cols)[*size] = depth;
    (*size)++;
    return;
  }
  for (int i = start; i < n; i++) {
    if (c[i] > target) {
      continue;
    }
    cur[depth] = c[i];
    dfs(c, n, target - c[i], i, cur, depth + 1, res, size, cols);
  }
}

int **combinationSum(int *candidates, int candidatesSize, int target, int *returnSize, int **returnColumnSizes) {
  int **res = (int **)malloc(sizeof(int *) * 1000);
  *returnColumnSizes = (int *)malloc(sizeof(int) * 1000);
  int *cur = (int *)malloc(sizeof(int) * 1000);
  *returnSize = 0;
  dfs(candidates, candidatesSize, target, 0, cur, 0, res, returnSize, returnColumnSizes);
  free(cur);
  return res;
}

class Solution {
  void dfs(vector<int> &candidates, int target, int start, vector<int> &cur, vector<vector<int>> &res) {
    if (target == 0) {
      res.push_back(cur);
      return;
    }
    for (int i = start; i < (int)candidates.size(); i++) {
      if (candidates[i] > target) {
        continue;
      }
      cur.push_back(candidates[i]);
      dfs(candidates, target - candidates[i], i, cur, res);
      cur.pop_back();
    }
  }

public:
  vector<vector<int>> combinationSum(vector<int> &candidates, int target) {
    vector<vector<int>> res;
    vector<int> cur;
    dfs(candidates, target, 0, cur, res);
    return res;
  }
};

func combinationSum(candidates []int, target int) [][]int {
	var res [][]int
	var cur []int
	var dfs func(start, remain int)
	dfs = func(start, remain int) {
		if remain == 0 {
			tmp := make([]int, len(cur))
			copy(tmp, cur)
			res = append(res, tmp)
			return
		}
		for i := start; i < len(candidates); i++ {
			if candidates[i] > remain {
				continue
			}
			cur = append(cur, candidates[i])
			dfs(i, remain-candidates[i])
			cur = cur[:len(cur)-1]
		}
	}
	dfs(0, target)
	return res
}

class Solution {
  private void dfs(int[] candidates, int target, int start, List<Integer> cur, List<List<Integer>> res) {
    if (target == 0) {
      res.add(new ArrayList<>(cur));
      return;
    }
    for (int i = start; i < candidates.length; i++) {
      if (candidates[i] > target) {
        continue;
      }
      cur.add(candidates[i]);
      dfs(candidates, target - candidates[i], i, cur, res);
      cur.remove(cur.size() - 1);
    }
  }

  public List<List<Integer>> combinationSum(int[] candidates, int target) {
    List<List<Integer>> res = new ArrayList<>();
    dfs(candidates, target, 0, new ArrayList<>(), res);
    return res;
  }
}

class Solution:
    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:
        res = []
        cur = []

        def dfs(start: int, remain: int):
            if remain == 0:
                res.append(cur[:])
                return
            for i in range(start, len(candidates)):
                if candidates[i] > remain:
                    continue
                cur.append(candidates[i])
                dfs(i, remain - candidates[i])
                cur.pop()

        dfs(0, target)
        return res

impl Solution {
  pub fn combination_sum(candidates: Vec<i32>, target: i32) -> Vec<Vec<i32>> {
    fn dfs(
      candidates: &[i32],
      remain: i32,
      start: usize,
      cur: &mut Vec<i32>,
      res: &mut Vec<Vec<i32>>,
    ) {
      if remain == 0 {
        res.push(cur.clone());
        return;
      }
      for i in start..candidates.len() {
        if candidates[i] > remain {
          continue;
        }
        cur.push(candidates[i]);
        dfs(candidates, remain - candidates[i], i, cur, res);
        cur.pop();
      }
    }
    let mut res = vec![];
    let mut cur = vec![];
    dfs(&candidates, target, 0, &mut cur, &mut res);
    res
  }
}

const combinationSum = (candidates: number[], target: number): number[][] => {
  const res: number[][] = [];
  const cur: number[] = [];

  const dfs = (start: number, remain: number) => {
    if (remain === 0) {
      res.push([...cur]);
      return;
    }
    for (let i = start; i < candidates.length; i++) {
      if (candidates[i] > remain) continue;
      cur.push(candidates[i]);
      dfs(i, remain - candidates[i]);
      cur.pop();
    }
  };

  dfs(0, target);
  return res;
};
